17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
106	        owner.setTelephone(normalizedTelephone);
107	        owner.setEmail(normalizeEmail(owner.getEmail()));
108	        if (owner.getRegistrationDate() == null) {
109	            owner.setRegistrationDate(java.time.LocalDate.now());
110	        }
111	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
112	            .map(Owner::getTelephone)
113	            .filter(java.util.Objects::nonNull)
114	            .map(telephone -> telephone.replaceAll("\\D", ""))
115	            .anyMatch(normalizedTelephone::equals);
116	        if (telephoneInUse) {
117	            throw new ResponseStatusException(HttpStatus.CONFLICT,
118	                "An owner with this telephone number already exists");
119	        }
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    /**
128	     * Normalizes a telephone number on create by stripping every non-digit character and
129	     * requiring exactly 10 digits. The stored/returned value is the resulting 10-digit string.
130	     *
131	     * @param telephone the raw telephone number as submitted
132	     * @return the normalized 10-digit telephone number
133	     * @throws ResponseStatusException with a 400 status if the value is not exactly 10 digits
134	     *         after stripping non-digit characters
135	     */
136	    private String normalizeTelephone(String telephone) {
137	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
138	        if (digits.length() != 10) {
139	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
140	                "Telephone must contain exactly 10 digits after removing non-digit characters");
141	        }
142	        return digits;
143	    }
144	
145	    /**
146	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
147	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
148	     * (absent) or already valid.
149	     *
150	     * @param email the email address as submitted, or {@code null} when absent
151	     * @return the lower-cased email, or {@code null} when absent
152	     */
153	    private String normalizeEmail(String email) {
154	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
160	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
161	        if (currentOwner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        currentOwner.setAddress(ownerFieldsDto.getAddress());
165	        currentOwner.setCity(ownerFieldsDto.getCity());
166	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
167	        currentOwner.setLastName(ownerFieldsDto.getLastName());
168	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
169	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
170	        this.clinicService.saveOwner(currentOwner);
171	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Transactional
176	    @Override
177	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        this.clinicService.deleteOwner(owner);
183	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
189	        Owner owner = this.clinicService.findOwnerById(ownerId);
190	        if (owner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        HttpHeaders headers = new HttpHeaders();
194	        Pet pet = petMapper.toPet(petFieldsDto);
195	        owner.setId(ownerId);
196	        pet.setOwner(owner);
197	        pet.getType().setName(null);
198	        this.clinicService.savePet(pet);
199	        PetDto petDto = petMapper.toPetDto(pet);
200	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
201	            .buildAndExpand(pet.getId()).toUri());
202	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
208	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
209	        if (currentOwner != null) {
210	            Pet currentPet = this.clinicService.findPetById(petId);
211	            if (currentPet != null) {
212	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
213	                currentPet.setName(petFieldsDto.getName());
214	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
215	                this.clinicService.savePet(currentPet);
216	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
225	        HttpHeaders headers = new HttpHeaders();
226	        Visit visit = visitMapper.toVisit(visitFieldsDto);
227	        Pet pet = new Pet();
228	        pet.setId(petId);
229	        visit.setPet(pet);
230	        this.clinicService.saveVisit(visit);
231	        VisitDto visitDto = visitMapper.toVisitDto(visit);
232	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
233	            .buildAndExpand(visit.getId()).toUri());
234	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
235	    }
236	
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner != null) {
243	            Pet pet = owner.getPet(petId);
244	            if (pet != null) {
245	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
246	            }
247	        }
248	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	    }
250	}
